-- Daily challenges for 2026-10-07: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-07

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('comparing-yourself-less', 'Comparing Yourself Less', 'For anyone who measures their life against other people''s highlights and comes up short. Each day is one small practice in noticing the comparison, stepping out of it, and coming back to your own pace, values and progress.', 'Confidence', 365, array['Self-Esteem', 'Self-Compassion']::text[], 1, '2026-10-07T17:00:00+00:00'::timestamptz),
  ('being-kinder-with-your-partner', 'Being Kinder with Your Partner', 'For couples who love each other and still slip into snapping, scorekeeping or taking each other for granted. Each day is one small, kind thing to say or do for your partner, so warmth gets a regular place in the everyday.', 'Relationships', 365, array['Relationships', 'Communication']::text[], 1, '2026-10-07T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('comparing-yourself-less', 'being-kinder-with-your-partner');

