  ('being-kinder-with-your-partner', 51, 'Bring your partner a glass of water or a snack while they are busy with something.'),
  ('being-kinder-with-your-partner', 52, 'Ask your partner what has felt heavy for them lately, and simply listen without trying to solve it.'),
  ('being-kinder-with-your-partner', 53, 'Mention one thing you admire about how your partner handles hard situations.'),
  ('being-kinder-with-your-partner', 54, 'Play a short game together tonight, cards, a puzzle or a word game, and keep it light.'),
  ('being-kinder-with-your-partner', 55, 'Remind yourself before you get home that your partner had a whole day you know little about.'),
  ('being-kinder-with-your-partner', 56, 'Check in with your partner at lunchtime to ask how the morning went.'),
  ('being-kinder-with-your-partner', 57, 'Notice when your partner is tired today, and offer to take one task off their evening.'),
  ('being-kinder-with-your-partner', 58, 'Offer your partner the more comfortable seat, the last bite or the warmer blanket.'),
  ('being-kinder-with-your-partner', 59, 'Before bed, say one thing you appreciated about your partner today.'),
  ('being-kinder-with-your-partner', 60, 'Laugh at your partner''s joke, even an old one, and let them see you enjoy it.'),
  ('being-kinder-with-your-partner', 61, 'Share a small worry of your own with your partner and let them comfort you.'),
